/* PF v1.4.3 bundle-command.js — concatenated bundle, generated by build/bundle.js.
   DO NOT EDIT. Regenerate with: node build/bundle.js [--debug]
   Contains: 00-shell.js, 01-request.js, 02-registry.js
   Each silo keeps its own PF.skip() kill switch (?pf_off=<silo>). */

/* ===== 00-shell.js ===== */
/* ============================================================================
   SILO: command/00-shell.js  |  PF v1.4.3 — Command Dashboard shell
   WHAT: #pf-command mount, ?pf_off=command kill switch, dark command-deck
         theme (ALL selectors scoped under #pf-command — zero global
         leakage), skeleton for callsign card → tiles → CTA slot →
         fronts → river (DOM order = mobile 390px stack order).
   WHY: branch 1 of the Command Dashboard build — the shell + request
         infrastructure the tile/front/river/CTA branches (2-5) plug into.
   KILL: ?pf_off=command  or  localStorage pf_disabled_v1='["command"]'
   ============================================================================ */
(function () {
  'use strict';

  /* Kill switch: honors PF.skip('command') when the core bus loaded, else
     parses ?pf_off= / pf_disabled_v1 directly (shell must die quietly even
     without the bus). */
  function pfOff() {
    try {
      if (window.PF && typeof window.PF.skip === 'function') return window.PF.skip('command');
    } catch (e) {}
    try {
      var m = (window.location.search || '').match(/[?&]pf_off=([^&]+)/);
      if (m) {
        var list = decodeURIComponent(m[1]).split(',');
        for (var i = 0; i < list.length; i++) if (list[i] === 'command') return true;
      }
      var d = [];
      try { d = JSON.parse((window.localStorage && window.localStorage.getItem('pf_disabled_v1')) || '[]'); } catch (e) {}
      return d.indexOf('command') !== -1;
    } catch (e) { return false; }
  }

  function isEditor() {
    try {
      var h = window.location.href || '';
      if (h.indexOf('/config/') !== -1) return true;
      var b = document.body;
      if (b && ((b.className || '').indexOf('sqs-edit') !== -1)) return true;
      return false;
    } catch (e) { return false; }
  }

  function mountRoot() {
    try { return document.getElementById('pf-command'); } catch (e) { return null; }
  }

  /* DARK COMMAND-DECK THEME. Every selector is rooted at #pf-command.
     Extractable for the theme-scoping test: wrapped in PFCMD-CSS markers. */
  var CSS =
    '/*PFCMD-CSS-START*/\n' +
    '#pf-command{background:#0a0a0c;color:#f5f0e1;font-family:"Helvetica Neue",Arial,sans-serif;padding:24px 16px;box-sizing:border-box;}\n' +
    '#pf-command .pfc-wrap{max-width:1100px;margin:0 auto;box-sizing:border-box;}\n' +
    '#pf-command .pfc-head{border-bottom:3px solid #c1121f;padding:0 0 12px;margin:0 0 16px;}\n' +
    '#pf-command .pfc-head h2{margin:0;font-size:34px;letter-spacing:2px;text-transform:uppercase;font-weight:900;color:#f5f0e1;}\n' +
    '#pf-command .pfc-head .pfc-sub{margin:6px 0 0;color:#f5a623;font-family:ui-monospace,Menlo,Consolas,monospace;font-size:12px;letter-spacing:1px;text-transform:uppercase;}\n' +
    '#pf-command .pfc-callsign{background:#111114;border:2px solid #c1121f;border-left:8px solid #c1121f;padding:14px 16px;margin:0 0 16px;}\n' +
    '#pf-command .pfc-callsign .pfc-cs-name{font-size:22px;font-weight:900;letter-spacing:1px;text-transform:uppercase;}\n' +
    '#pf-command .pfc-callsign .pfc-cs-data{font-family:ui-monospace,Menlo,Consolas,monospace;color:#f5a623;font-size:13px;margin-top:6px;}\n' +
    '#pf-command .pfc-callsign .pfc-cs-data .pfc-status{color:#f5a623;}\n' +
    '#pf-command .pfc-tiles{display:grid;grid-template-columns:repeat(auto-fill,minmax(240px,1fr));gap:12px;margin:0 0 16px;}\n' +
    '#pf-command .pfc-tile{background:#111114;border:1px solid #333;border-top:3px solid #c1121f;padding:12px;min-height:120px;}\n' +
    '#pf-command .pfc-tile .pfc-tile-title{font-weight:800;letter-spacing:1px;text-transform:uppercase;font-size:14px;margin:0 0 8px;color:#f5f0e1;}\n' +
    '#pf-command .pfc-tile .pfc-tile-body{font-family:ui-monospace,Menlo,Consolas,monospace;color:#f5a623;font-size:12px;}\n' +
    '#pf-command .pfc-tile.pfc-tile-loading{opacity:.55;}\n' +
    '#pf-command .pfc-tile.pfc-tile-error{border-top-color:#555;}\n' +
    '#pf-command .pfc-tile.pfc-tile-error .pfc-tile-body{color:#8a8578;}\n' +
    '#pf-command .pfc-tile.pfc-tile-locked{border-top-color:#f5a623;min-height:0;}\n' +
    '#pf-command .pfc-tile .pfc-retry{background:transparent;border:1px solid #c1121f;color:#f5f0e1;font-family:ui-monospace,Menlo,Consolas,monospace;font-size:11px;padding:6px 10px;cursor:pointer;margin-top:8px;}\n' +
    '#pf-command .pfc-cta{margin:0 0 16px;}\n' +
    '#pf-command .pfc-cta:empty{display:none;}\n' +
    '#pf-command .pfc-fronts{margin:0 0 16px;border-top:3px solid #c1121f;padding-top:12px;}\n' +
    '#pf-command .pfc-fronts:empty{display:none;}\n' +
    '#pf-command .pfc-river{margin:0 0 16px;border-top:3px solid #c1121f;padding-top:12px;}\n' +
    '#pf-command .pfc-river:empty{display:none;}\n' +
    '#pf-command .pfc-sec-label{font-size:20px;font-weight:900;letter-spacing:2px;text-transform:uppercase;margin:0 0 10px;color:#f5f0e1;}\n' +
    '#pf-command .pfc-recruit{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:12px;margin:0 0 16px;}\n' +
    '#pf-command .pfc-mission{background:#111114;border:2px solid #c1121f;padding:16px;}\n' +
    '#pf-command .pfc-mission .pfc-m-num{font-family:ui-monospace,Menlo,Consolas,monospace;color:#f5a623;font-size:12px;letter-spacing:2px;}\n' +
    '#pf-command .pfc-mission h3{margin:8px 0;font-size:20px;text-transform:uppercase;letter-spacing:1px;color:#f5f0e1;}\n' +
    '#pf-command .pfc-mission p{font-size:13px;color:#b9b3a6;margin:0 0 12px;line-height:1.5;}\n' +
    '#pf-command .pfc-mission .pfc-m-links{display:flex;gap:8px;flex-wrap:wrap;}\n' +
    '#pf-command .pfc-btn{display:inline-block;background:#c1121f;color:#fff;text-decoration:none;font-weight:800;letter-spacing:1px;text-transform:uppercase;padding:10px 18px;font-size:13px;}\n' +
    '#pf-command .pfc-btn.pfc-btn-ghost{background:transparent;border:2px solid #c1121f;color:#f5f0e1;}\n' +
    '#pf-command .pfc-footnote{font-family:ui-monospace,Menlo,Consolas,monospace;color:#6d685c;font-size:11px;margin:12px 0 0;letter-spacing:1px;text-transform:uppercase;}\n' +
    '@media (max-width:480px){\n' +
    '#pf-command{padding:16px 10px;}\n' +
    '#pf-command .pfc-head h2{font-size:26px;}\n' +
    '#pf-command .pfc-tiles{grid-template-columns:1fr;}\n' +
    '#pf-command .pfc-recruit{grid-template-columns:1fr;}\n' +
    '}\n' +
    '/*PFCMD-CSS-END*/';

  function injectTheme(root) {
    var st = document.createElement('style');
    try { st.setAttribute('data-pf', 'command-theme'); } catch (e) {}
    st.textContent = CSS;
    root.appendChild(st);
  }

  /* Skeleton: DOM order = mobile 390px stack order
     (callsign card → tiles → CTA slot → fronts → river). */
  function buildSkeleton(root) {
    var wrap = document.createElement('div');
    wrap.className = 'pfc-wrap';
    wrap.innerHTML =
      '<div class="pfc-head"><h2>Command Deck</h2>' +
      '<div class="pfc-sub">SITREP // ALL FRONTS // LIVE</div></div>' +
      '<div class="pfc-callsign"></div>' +
      '<div class="pfc-tiles"></div>' +
      '<div class="pfc-cta"></div>' +
      '<div class="pfc-fronts"></div>' +
      '<div class="pfc-river"></div>' +
      '<div class="pfc-footnote">PROPAGANDA FACTORY COMMAND // JOIN THE FIGHT.</div>';
    root.appendChild(wrap);
    return wrap;
  }

  var NS = window.PFCommand || (window.PFCommand = {});
  NS._shell = {
    pfOff: pfOff,
    isEditor: isEditor,
    mountRoot: mountRoot,
    CSS: CSS,
    injectTheme: injectTheme,
    buildSkeleton: buildSkeleton
  };
})();

;

/* ===== 01-request.js ===== */
/* ============================================================================
   SILO: command/01-request.js  |  PF v1.4.3 — Command Dashboard request infra
   WHAT: the shared transport every command-dashboard branch uses.
         - NS.jsonp(action, params) -> Promise, 12s timeout, FAIL-SOFT
           (resolves {ok:false, error} — never rejects, never throws).
         - Concurrency cap: ~6 in-flight JSONP requests, overflow queues.
         - NS.whenVisible(el, cb): IntersectionObserver staggering for
           below-fold tiles (200px rootMargin prefetch); immediate fallback
           when IntersectionObserver is unavailable.
         - NS.callsign(): callsign from pf_identity_v1, '' when logged out.
         - NS.esc / NS.el: shared text-escaping + element helpers.
   WHY: one scheduler means tiles can't stampede the backend; one timeout
         rule means one bad tile can't stall the deck.
   KILL: inherits the shell kill (?pf_off=command).
   ============================================================================ */
(function () {
  'use strict';
  var NS = window.PFCommand || (window.PFCommand = {});

  function backendUrl() {
    try { return window.PF_BACKEND_URL || ''; } catch (e) { return ''; }
  }

  NS._timeoutMs = 12000;      /* 12s fail-soft per request (tests may lower) */
  NS._maxInflight = 6;        /* ~6 concurrent JSONP requests */
  NS._observedMax = 0;        /* high-water mark, for tests/QC */

  var inFlight = 0, queue = [], seq = 0;
  NS._inFlight = function () { return inFlight; };
  NS._queueLen = function () { return queue.length; };

  function finishJob(job, res, err) {
    try { delete window[job.fn]; } catch (e) {}
    try { if (job.script && job.script.parentNode) job.script.parentNode.removeChild(job.script); } catch (e) {}
    inFlight--;
    pump();
    if (res && res.ok !== false) job.resolve({ ok: true, data: res });
    else job.resolve({ ok: false, data: res || null, error: err || 'fetch-failed' });
  }

  function runJob(job) {
    var done = false, timer = null;
    job.script = null; job.fn = '';
    function finish(res, err) {
      if (done) return; done = true;
      if (timer) { try { clearTimeout(timer); } catch (e) {} }
      finishJob(job, res, err);
    }
    try {
      var base = backendUrl();
      if (!base) { finish(null, 'no-backend'); return; }
      seq++;
      var fn = 'pfCmdCb' + Math.floor(Math.random() * 1e9) + '_' + seq;
      job.fn = fn;
      window[fn] = function (j) { finish(j, null); };
      var q = '?action=' + encodeURIComponent(job.action);
      var p = job.params || {};
      for (var k in p) {
        if (p[k] != null && p[k] !== '') q += '&' + encodeURIComponent(k) + '=' + encodeURIComponent(p[k]);
      }
      q += '&callback=' + fn;
      var s = document.createElement('script');
      s.async = true;
      s.onerror = function () { finish(null, 'load-error'); };
      s.src = base + q;
      job.script = s;
      document.head.appendChild(s);
      timer = setTimeout(function () { finish(null, 'timeout'); }, NS._timeoutMs);
    } catch (e) { finish(null, 'exception'); }
  }

  function pump() {
    while (inFlight < NS._maxInflight && queue.length) {
      var job = queue.shift();
      inFlight++;
      if (inFlight > NS._observedMax) NS._observedMax = inFlight;
      runJob(job);
    }
  }

  /* Fail-soft JSONP: the Promise NEVER rejects. */
  NS.jsonp = function (action, params) {
    return new Promise(function (resolve) {
      queue.push({ action: action, params: params || {}, resolve: resolve });
      pump();
    });
  };

  /* Staggered loading for below-fold tiles. Fires cb once, on first
     visibility (200px prefetch margin); fires immediately when
     IntersectionObserver is unavailable. */
  NS.whenVisible = function (el, cb) {
    var fired = false;
    function fire() {
      if (fired) return; fired = true;
      try { cb(); } catch (e) { NS.log('whenVisible', e); }
    }
    try {
      var IO = null;
      try { IO = window.IntersectionObserver || IntersectionObserver; } catch (e) {}
      if (IO && el) {
        var io = new IO(function (entries) {
          for (var i = 0; i < entries.length; i++) {
            if (entries[i].isIntersecting) { try { io.disconnect(); } catch (e) {} fire(); return; }
          }
        }, { rootMargin: '200px' });
        io.observe(el);
        return;
      }
    } catch (e) {}
    setTimeout(fire, 0);
  };

  /* '' when logged out (no callsign) — drives auth-gated tiles. */
  NS.callsign = function () {
    try {
      var id = JSON.parse((window.localStorage && window.localStorage.getItem('pf_identity_v1')) || '{}');
      return (id && id.callsign) ? String(id.callsign).toUpperCase() : '';
    } catch (e) { return ''; }
  };

  NS.esc = function (s) {
    return String(s == null ? '' : s).replace(/[&<>"']/g, function (c) {
      return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c];
    });
  };

  NS.el = function (tag, cls, html) {
    var d = document.createElement(tag || 'div');
    if (cls) d.className = cls;
    if (html != null) d.innerHTML = html;
    return d;
  };

  NS.log = function (silo, err) {
    try { console.error('[PFCommand:' + silo + '] ' + (err && err.message ? err.message : err)); }
    catch (e) {}
  };
})();

;

/* ===== 02-registry.js ===== */
/* ============================================================================
   SILO: command/02-registry.js  |  PF v1.4.3 — Command Dashboard registry
   WHAT: the plug-in contract the other dashboard branches build against.
     NS.registerTile({id, label, auth, priority, fetch, render,
                      skeleton, loggedOut})   -> slot: tiles grid
     NS.registerCTA({id, render})              -> CTA slot
     NS.registerFront({id, render})            -> fronts section
     NS.registerRiver({id, render})            -> river section
   Tile lifecycle: skeleton -> whenVisible (staggered) -> auth gate ->
     fetch() returns {action, params} (existing backend actions ONLY —
     no new endpoints) -> NS.jsonp (cap 6, 12s fail-soft) ->
     render(card, data) | error card with RETRY (never breaks neighbors).
   RECRUIT MODE: when fewer than 3 tiles have data after the first settle,
     the tiles grid renders the first-mission sequence instead:
     claim callsign -> check in -> join cell / quiz (deep links to the
     existing homepage, /cells, /arcade — no new endpoints, no XP grants).
   KILL: inherits the shell kill (?pf_off=command).
   ============================================================================ */
(function () {
  'use strict';
  var NS = window.PFCommand || (window.PFCommand = {});
  var shell = NS._shell;

  var tiles = [], ctas = [], fronts = [], river = [];
  NS.registerTile = function (def) { if (def && def.id) { tiles.push(def); mountLate('tiles', def); } };
  NS.registerCTA = function (def) { if (def && def.id) { ctas.push(def); mountLate('cta', def); } };
  NS.registerFront = function (def) { if (def && def.id) { fronts.push(def); mountLate('fronts', def); } };
  NS.registerRiver = function (def) { if (def && def.id) { river.push(def); mountLate('river', def); } };

  var booted = false;
  var wrapEl = null, slotEls = {};
  var pendingTiles = 0, tilesWithData = 0, recruitChecked = false;
  NS._tilesWithData = function () { return tilesWithData; };
  NS._pendingTiles = function () { return pendingTiles; };

  function firstChildByClass(root, cls) {
    var kids = root.children || [];
    for (var i = 0; i < kids.length; i++) {
      if ((' ' + (kids[i].className || '') + ' ').indexOf(' ' + cls + ' ') !== -1) return kids[i];
    }
    return null;
  }

  /* ---------- callsign card ---------- */
  function renderCallsignCard(root) {
    var card = firstChildByClass(wrapEl, 'pfc-callsign');
    if (!card) return;
    var cs = NS.callsign();
    if (cs) {
      card.innerHTML =
        '<div class="pfc-cs-name">' + NS.esc(cs) + '</div>' +
        '<div class="pfc-cs-data">XP TODAY: <span class="pfc-xp">···</span> // ' +
        'STATUS: <span class="pfc-status">ONLINE</span></div>';
      NS.jsonp('xp_today', { callsign: cs }).then(function (res) {
        try {
          var v = (res.ok && res.data && typeof res.data.xp_today === 'number')
            ? String(Math.floor(res.data.xp_today)) : '—';
          card.innerHTML =
            '<div class="pfc-cs-name">' + NS.esc(cs) + '</div>' +
            '<div class="pfc-cs-data">XP TODAY: <span class="pfc-xp">' + NS.esc(v) +
            '</span> // STATUS: <span class="pfc-status">ONLINE</span></div>';
        } catch (e) {}
      });
    } else {
      card.innerHTML =
        '<div class="pfc-cs-name">UNENLISTED</div>' +
        '<div class="pfc-cs-data">STATUS: <span class="pfc-status">RECRUIT</span> // ' +
        'CLAIM A CALLSIGN TO LIGHT UP THIS DECK</div>' +
        /* 2026-10-06 CEO directive: every claim prompt needs the recovery path. */
        (function(){ try{ return (window.PF && window.PF.recoverLinkHTML) ? window.PF.recoverLinkHTML() : ''; }catch(e){ return ''; } })();
    }
  }

  /* ---------- tiles ---------- */
  function defaultSkeleton(card, def) {
    card.innerHTML =
      '<div class="pfc-tile-title">' + NS.esc(def.label || def.id) + '</div>' +
      '<div class="pfc-tile-body">ESTABLISHING UPLINK···</div>';
  }

  function renderLocked(card, def) {
    card.className = 'pfc-tile pfc-tile-locked';
    if (typeof def.loggedOut === 'function') { try { def.loggedOut(card); return; } catch (e) {} }
    card.innerHTML =
      '<div class="pfc-tile-title">' + NS.esc(def.label || def.id) + '</div>' +
      '<div class="pfc-tile-body">ENLIST TO UNLOCK — <a href="/" style="color:#f5a623">CLAIM CALLSIGN</a></div>';
  }

  function renderError(card, def, err) {
    card.className = 'pfc-tile pfc-tile-error';
    card.innerHTML =
      '<div class="pfc-tile-title">' + NS.esc(def.label || def.id) + '</div>' +
      '<div class="pfc-tile-body">SIGNAL LOST (' + NS.esc(err || 'fetch-failed') + ')</div>' +
      '<button type="button" class="pfc-retry">RETRY</button>';
    try {
      var btn = card.children[card.children.length - 1];
      if (btn && btn.addEventListener) btn.addEventListener('click', function () { startTile(card, def, true); });
    } catch (e) {}
  }

  function startTile(card, def, retry) {
    card.className = 'pfc-tile pfc-tile-loading';
    if (def.auth && !NS.callsign()) { renderLocked(card, def); settleTile(false); return; }
    var spec = null;
    try { spec = (typeof def.fetch === 'function') ? def.fetch() : null; } catch (e) { spec = null; }
    if (!spec || !spec.action) { renderError(card, def, 'no-action'); settleTile(false); return; }
    NS.jsonp(spec.action, spec.params || {}).then(function (res) {
      if (res && res.ok) {
        try {
          card.className = 'pfc-tile';
          def.render(card, res.data);
          settleTile(true);
        } catch (e) { NS.log('tile:' + def.id, e); renderError(card, def, 'render-error'); settleTile(false); }
      } else {
        renderError(card, def, res && res.error);
        settleTile(false);
      }
    });
  }

  function mountTile(def) {
    var grid = slotEls.tiles;
    if (!grid) return;
    var card = NS.el('div', 'pfc-tile pfc-tile-loading');
    try {
      if (typeof def.skeleton === 'function') def.skeleton(card);
      else defaultSkeleton(card, def);
    } catch (e) { defaultSkeleton(card, def); }
    grid.appendChild(card);
    pendingTiles++;
    NS.whenVisible(card, function () { startTile(card, def, false); });
  }

  function settleTile(hadData) {
    if (hadData) tilesWithData++;
    pendingTiles--;
    if (pendingTiles <= 0 && !recruitChecked) {
      recruitChecked = true;
      maybeRecruitMode();
    }
  }

  /* ---------- recruit mode ---------- */
  function maybeRecruitMode() {
    var grid = slotEls.tiles;
    if (!grid || tilesWithData >= 3) return;
    grid.innerHTML = '';
    var seq = NS.el('div', 'pfc-recruit');
    seq.innerHTML =
      '<div class="pfc-mission">' +
        '<div class="pfc-m-num">MISSION 01 // IDENTITY</div>' +
        '<h3>Claim your callsign</h3>' +
        '<p>Every operative needs a name. Enlist on the homepage and your command deck lights up.</p>' +
        '<div class="pfc-m-links"><a class="pfc-btn" href="/">Enlist →</a></div>' +
        /* 2026-10-06 CEO directive: every claim prompt needs the recovery path. */
        (function(){ try{ return (window.PF && window.PF.recoverLinkHTML) ? window.PF.recoverLinkHTML() : ''; }catch(e){ return ''; } })() +
      '</div>' +
      '<div class="pfc-mission">' +
        '<div class="pfc-m-num">MISSION 02 // DUTY</div>' +
        '<h3>Check in</h3>' +
        '<p>Report for duty with Daily Orders. One check-in a day keeps your streak — and your rank — alive.</p>' +
        '<div class="pfc-m-links"><a class="pfc-btn" href="/">Daily Orders →</a></div>' +
      '</div>' +
      '<div class="pfc-mission">' +
        '<div class="pfc-m-num">MISSION 03 // DEPLOY</div>' +
        '<h3>Join the fight</h3>' +
        '<p>Link up with a cell for coordinated ops, or take the quiz to find your propagandist archetype.</p>' +
        '<div class="pfc-m-links">' +
          '<a class="pfc-btn" href="/cells">Join a cell →</a>' +
          '<a class="pfc-btn pfc-btn-ghost" href="/arcade">Take the quiz →</a>' +
        '</div>' +
      '</div>';
    grid.appendChild(seq);
  }

  /* ---------- other slots ---------- */
  function mountSimple(slot, def) {
    var host = slotEls[slot];
    if (!host) return;
    var box = NS.el('div', 'pfc-' + slot + '-item');
    host.appendChild(box);
    NS.whenVisible(box, function () {
      try { def.render(box); } catch (e) { NS.log(slot + ':' + def.id, e); }
    });
  }

  function mountLate(slot, def) {
    /* Registrations that arrive after boot (later script bundles) mount on
       the fly instead of being dropped. */
    if (!booted) return;
    try {
      if (slot === 'tiles') mountTile(def);
      else mountSimple(slot, def);
    } catch (e) { NS.log('mountLate:' + slot, e); }
  }

  /* ---------- boot ---------- */
  function boot() {
    if (booted) return;
    /* Kill switch: hide the whole mount, do zero work, throw zero errors. */
    if (shell.pfOff() || shell.isEditor()) {
      var m = shell.mountRoot();
      if (m) { try { m.innerHTML = ''; m.style.display = 'none'; } catch (e) {} }
      return;
    }
    var root = shell.mountRoot();
    if (!root) return;
    try {
      shell.injectTheme(root);
      wrapEl = shell.buildSkeleton(root);
      var kids = wrapEl.children || [];
      slotEls = {
        callsign: firstChildByClass(wrapEl, 'pfc-callsign'),
        tiles: firstChildByClass(wrapEl, 'pfc-tiles'),
        cta: firstChildByClass(wrapEl, 'pfc-cta'),
        fronts: firstChildByClass(wrapEl, 'pfc-fronts'),
        river: firstChildByClass(wrapEl, 'pfc-river')
      };
      booted = true;
      renderCallsignCard(root);
      /* Tiles first (priority order), then CTA / fronts / river. */
      var ordered = tiles.slice().sort(function (a, b) {
        return (a.priority || 99) - (b.priority || 99);
      });
      ordered.forEach(mountTile);
      ctas.forEach(function (d) { mountSimple('cta', d); });
      fronts.forEach(function (d) { mountSimple('fronts', d); });
      river.forEach(function (d) { mountSimple('river', d); });
      /* No tiles registered yet (branches 2-5 not merged) → run the recruit
         check on the next tick so recruit mode renders by default. */
      if (pendingTiles === 0 && !recruitChecked) {
        setTimeout(function () {
          if (!recruitChecked && pendingTiles === 0) { recruitChecked = true; maybeRecruitMode(); }
        }, 0);
      }
    } catch (e) { NS.log('boot', e); }
  }

  NS.boot = boot;

  try {
    if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', boot);
    else boot();
  } catch (e) { /* never throw at load time */ }
})();

